from typing import List

def rankTeams(votes: List[str]) -> str:
    # Create a dictionary to store the rank counts for each team
    rank_counts = {team: [0] * len(votes[0]) for team in votes[0]}

    # Count the ranks for each team
    for vote in votes:
        for rank, team in enumerate(vote):
            rank_counts[team][rank] -= 1

    # Sort the teams based on the rank counts and then alphabetically
    sorted_teams = sorted(votes[0], key=lambda team: (rank_counts[team], team))

    # Join the sorted teams into a single string
    return ''.join(sorted_teams)
